'use client';

import React from 'react';
import CheckCircleRoundedIcon from '@mui/icons-material/CheckCircleRounded';
import { Button } from '@/components/Button';
import { InvestmentPlan } from '@/types/TradingHouseType';
import {
  formatAmount,
  formatDuration,
  formatPercent,
} from '@/utils/invest_helper';

type Props = {
  plan: InvestmentPlan;
  houseName?: string;
  onInvest: () => void;
};

export const PlanCard: React.FC<Props> = ({ plan, houseName, onInvest }) => (
  <div
    style={{
      position: 'relative',
      height: '100%',
      display: 'flex',
      flexDirection: 'column',
      gap: 12,
      padding: 20,
      borderRadius: 24,
      backgroundColor: plan.popular ? 'var(--main-color)' : 'var(--white-color)',
      border: `1px solid ${plan.popular ? 'var(--main-color)' : 'var(--border-color)'}`,
    }}
  >
    {plan.popular && (
      <span
        style={{
          position: 'absolute',
          top: -12,
          right: 20,
          padding: '2px 12px',
          borderRadius: 20,
          fontSize: 12,
          fontWeight: 600,
          backgroundColor: 'var(--accent-color)',
          color: 'var(--main-color)',
        }}
      >
        Populaire
      </span>
    )}
    <div>
      {houseName && (
        <span
          className="t12"
          style={{ color: plan.popular ? '#c8cdd9' : undefined }}
        >
          {houseName}
        </span>
      )}
      <h4 style={{ color: plan.popular ? 'var(--white-color)' : undefined }}>
        {plan.name}
      </h4>
    </div>
    <div style={{ display: 'flex', alignItems: 'baseline', gap: 6 }}>
      <span
        style={{
          fontSize: 34,
          fontWeight: 800,
          lineHeight: 1,
          color: plan.popular ? 'var(--accent-color)' : 'var(--success-color)',
        }}
      >
        {formatPercent(plan.expectedReturn, true)}
      </span>
      <span
        className="t14"
        style={{ color: plan.popular ? '#c8cdd9' : undefined }}
      >
        en {formatDuration(plan.durationDays)}
      </span>
    </div>
    <ul style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
      {[
        `De ${formatAmount(plan.minAmount)} à ${formatAmount(plan.maxAmount)}`,
        `Versement des gains : ${plan.payout}`,
        ...plan.features,
      ].map((feature) => (
        <li
          key={feature}
          className="t14"
          style={{
            display: 'flex',
            gap: 8,
            alignItems: 'flex-start',
            color: plan.popular ? 'var(--white-color)' : undefined,
          }}
        >
          <CheckCircleRoundedIcon
            sx={{ fontSize: 18, mt: '2px', color: 'var(--accent-color)' }}
          />
          {feature}
        </li>
      ))}
    </ul>
    <Button
      label="Investir"
      containerStyle={{ marginTop: 'auto' }}
      onClick={(event: React.MouseEvent) => {
        event.preventDefault();
        onInvest();
      }}
    />
  </div>
);
